import{_ as i,o as a,c as e,ag as l}from"./chunks/framework.PVHj0As1.js";const n="/pub-blog/assets/image-20240608002954074.BnxIRVR9.png",p="/pub-blog/assets/image-20240608004247416.D6K3M-wL.png",t="/pub-blog/assets/image-20240608004726930.0ymRP1jJ.png",r="/pub-blog/assets/image-20240608004827845.DCeOGnei.png",h="/pub-blog/assets/image-20240608005114527.ChD8xQ3a.png",k="/pub-blog/assets/image-20240608005144778.CFF5YU_f.png",o="/pub-blog/assets/image-20240608005334602.C3OJ2NV1.png",E="/pub-blog/assets/image-20240608005438191.DqCnfY03.png",c="/pub-blog/assets/image-20240608010002233.BXLMRlML.png",m="/pub-blog/assets/image-20240608010016337.Bn-rfBHn.png",F=JSON.parse(`{"title":"高质量 HarmonyOS  权限管控流程","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/鸿蒙应用开发权限一览/鸿蒙应用开发权限一览.md","filePath":"鸿蒙开发技巧/鸿蒙应用开发权限一览/鸿蒙应用开发权限一览.md","lastUpdated":1730788610000,"__rawMarkdown":"# 高质量 HarmonyOS  权限管控流程 \\n\\n在 **HarmonyOS** 应用开发过程中，往往会涉及到**敏感数据**和**硬件资源**的调动和访问，而这部分的调用就会涉及到管控这部分的知识和内容了。我们需要对它有所了解，才可以在应用开发中提高效率和避免踩坑。\\n\\n\\n\\n\\n\\n## 权限管控了什么\\n\\n权限管控，主要是管控 **数据**和**功能**。\\n\\n- 数据包括个人数据（如照片、通讯录、日历、位置等）、设备数据（如设备标识、相机、麦克风等）。\\n- 功能包括设备功能（如访问摄像头/麦克风、打电话、联网等）、应用功能（如弹出悬浮窗、创建快捷方式等）。\\n\\n\\n\\n## 权限组和子权限\\n\\n我们先看什么是子权限。比如对于媒体相册的功能操作来说。读取相册内容是一种权限、写入内容到相册是一种权限。 那么它们属于媒体相册这个大权限中的子权限。那么我们的应用在申请媒体相册的读写权限时，考虑到用户的体验。其实是会把两个权限合并为一个弹出窗口，询问用户授予权限。如果用户允许了，那么就等于获得了媒体相册的读写权限了。总结就是\\n\\n- 读取媒体相册是子权限、写入媒体相册是子权限\\n- 它们合起来就是一个权限组。\\n\\n![image-20240608002954074](readme.assets/image-20240608002954074.png)\\n\\n## 权限组和子权限一览\\n\\n> [链接](https://docs.openharmony.cn/pages/v4.1/zh-cn/application-dev/security/AccessToken/app-permission-group-list.md)\\n\\n\`\`\`ts\\n位置信息\\nohos.permission.LOCATION_IN_BACKGROUND\\n\\nohos.permission.LOCATION\\n\\nohos.permission.APPROXIMATELY_LOCATION\\n\\n相机\\nohos.permission.CAMERA\\n麦克风\\nohos.permission.MICROPHONE\\n通讯录\\nohos.permission.READ_CONTACTS\\n\\nohos.permission.WRITE_CONTACTS\\n\\n日历\\nohos.permission.READ_CALENDAR\\n\\nohos.permission.WRITE_CALENDAR\\n\\nohos.permission.READ_WHOLE_CALENDAR\\n\\nohos.permission.WRITE_WHOLE_CALENDAR\\n\\n健身运动\\nohos.permission.ACTIVITY_MOTION\\n身体传感器\\nohos.permission.READ_HEALTH_DATA\\n图片和视频\\nohos.permission.WRITE_IMAGEVIDEO\\n\\nohos.permission.READ_IMAGEVIDEO\\n\\nohos.permission.MEDIA_LOCATION\\n\\n音乐和音频\\nohos.permission.WRITE_AUDIO\\n\\nohos.permission.READ_AUDIO\\n\\n文件\\nohos.permission.READ_DOCUMENT\\n\\nohos.permission.WRITE_DOCUMENT\\n\\nohos.permission.READ_MEDIA\\n\\nohos.permission.WRITE_MEDIA\\n\\n广告跟踪\\nohos.permission.APP_TRACKING_CONSENT\\n读取已安装应用列表\\nohos.permission.GET_INSTALLED_BUNDLE_LIST\\n多设备协同\\nohos.permission.DISTRIBUTED_DATASYNC\\n蓝牙\\nohos.permission.ACCESS_BLUETOOTH\\n电话\\nohos.permission.ANSWER_CALL\\n\\nohos.permission.MANAGE_VOICEMAIL\\n\\n通话记录\\nohos.permission.READ_CALL_LOG\\n\\nohos.permission.WRITE_CALL_LOG\\n\\n信息\\nohos.permission.READ_CELL_MESSAGES\\n\\nohos.permission.READ_MESSAGES\\n\\nohos.permission.RECEIVE_MMS\\n\\nohos.permission.RECEIVE_SMS\\n\\nohos.permission.RECEIVE_WAP_MESSAGES\\n\\nohos.permission.SEND_MESSAGES\\n\\n剪切板\\nohos.permission.READ_PASTEBOARD\\n文件夹\\nohos.permission.READ_WRITE_DOWNLOAD_DIRECTORY\\n\\nohos.permission.READ_WRITE_DESKTOP_DIRECTORY\\n\\nohos.permission.READ_WRITE_DOCUMENTS_DIRECTORY\\n\`\`\`\\n\\n\\n\\n## APL等级\\n\\nAPL（Ability Privilege Level，元能力权限等级）等级，分为两类。一类是**应用APL等级**、另一类是**权限APL等级**。说人话就是 不管官阶的士官和其对应的权限之间的关系。\\n\\n### 应用APL等级\\n\\n应用APL等级分为三级：\\n\\n| APL级别      | 说明                                                         |\\n| :----------- | :----------------------------------------------------------- |\\n| normal       | 默认情况下，应用的APL等级都为normal等级。                    |\\n| system_basic | 该等级的应用服务提供系统基础服务。                           |\\n| system_core  | 该等级的应用服务提供操作系统核心能力。 应用APL等级不允许配置为system_core。 |\\n\\n### 权限APL等级\\n\\n权限APL等级也分为三级：\\n\\n| APL级别      | 说明                                                         | 开放范围                                            |\\n| :----------- | :----------------------------------------------------------- | :-------------------------------------------------- |\\n| normal       | 允许应用访问超出默认规则外的普通系统资源，如配置Wi-Fi信息、调用相机拍摄等。 这些系统资源的开放（包括数据和功能）对用户隐私以及其他应用带来的风险低。 | APL等级为normal及以上的应用。                       |\\n| system_basic | 允许应用访问操作系统基础服务（系统提供或者预置的基础功能）相关的资源，如系统设置、身份认证等。 这些系统资源的开放对用户隐私以及其他应用带来的风险较高。 | APL等级为system_basic及以上的应用。                 |\\n| system_core  | 涉及开放操作系统核心资源的访问操作。这部分系统资源是系统最核心的底层服务，如果遭受破坏，操作系统将无法正常运行。 | - APL等级为system_core的应用。 - 仅对系统应用开放。 |\\n\\n## 访问控制列表（ACL）\\n\\n**权限等级**和应用APL等级是一一对应的。原则上，拥有低APL等级的应用默认无法申请更高等级的权限。访问控制列表**ACL（Access Control List）**提供了解决低等级应用访问高等级权限问题的特殊渠道。我们可以将ACL理解为**让普通的老百姓也具有某种士官的能力，如调兵遣将**。\\n\\n需要注意的是，并不是所有的权限都能通过申请ACL来实现跨等级的应用来获得。具体哪些权限可以被跨等级申请使用。**HarmonyOS**中也有明确标识的。如：  [链接](https://docs.openharmony.cn/pages/v4.1/zh-cn/application-dev/security/AccessToken/permissions-for-all.md#systemgrant%E7%B3%BB%E7%BB%9F%E6%8E%88%E6%9D%83%E6%9D%83%E9%99%90%E5%88%97%E8%A1%A8)\\n\\n![image-20240608004247416](readme.assets/image-20240608004247416.png)\\n\\n\\n\\n## 授权方式\\n\\n不管是什么的方式申请权限，最后在用户的体验上一共分为两种。 system_grant（系统授权） 和  user_grant（用户授权）\\n\\n1. system_grant（系统授权）\\n\\n   - 应用被允许访问的数据不会涉及到用户或设备的敏感信息\\n   - 需要在安装包中申请system_grant权限，那么系统会在用户安装应用时，**自动把相应权限授予给应用**。\\n\\n2. user_grant（用户授权）\\n\\n   - **会弹出窗口询问用户的意见**-应用被允许访问的数据将会涉及到用户或设备的敏感信息\\n\\n     \\n\\n   - 需要注意的是，如果用户增加拒绝过授权，那么只能通过引导用户到系统设置页面来手动打开权限\\n\\n   ![image-20240608004726930](readme.assets/image-20240608004726930.png)\\n\\n## 申请应用权限流程\\n\\n一图胜万言\\n\\n### 总流程图\\n\\n![image-20240608004827845](readme.assets/image-20240608004827845.png)\\n\\n---\\n\\n\\n\\n### normal等级的应用申请权限\\n\\n![image-20240608005114527](readme.assets/image-20240608005114527.png)\\n\\n###  system_basic等级的应用申请权限\\n\\n![image-20240608005144778](readme.assets/image-20240608005144778.png)\\n\\n## 申请应用权限操作步骤\\n\\n### 1.声明权限-必须\\n\\n1. 在 **main/module.json5** 中  配置  **requestPermissions** 字段声明权限\\n\\n2. 配置内容\\n\\n   ![image-20240608005334602](readme.assets/image-20240608005334602.png)\\n\\n### 2.声明ACL权限-非必须 \\n\\n> [参考链接](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/ide-signing-0000001587684945)\\n\\n![image-20240608005438191](readme.assets/image-20240608005438191.png)\\n\\n### 3.向用户申请授权-非必须\\n\\n如果你申请的权限类型是 **system_grant（系统授权）**，那么可以跳过这个步骤。如果你申请的权限类型是 **user_grant（用户授权）**，那么需要主动申请权限，此时用户会弹出对话框。如\\n\\n\`\`\`ts\\nimport abilityAccessCtrl, { Context, PermissionRequestResult } from '@ohos.abilityAccessCtrl';\\nimport { BusinessError } from '@ohos.base';\\nimport common from '@ohos.app.ability.common';\\n\\nlet atManager: abilityAccessCtrl.AtManager = abilityAccessCtrl.createAtManager();\\nlet context: Context = getContext(this) as common.UIAbilityContext;\\n// 申请摄像头权限\\natManager.requestPermissionsFromUser(context, ['ohos.permission.CAMERA']).then((data: PermissionRequestResult) => {\\n  console.info('data:' + JSON.stringify(data));\\n  console.info('data permissions:' + data.permissions);\\n  console.info('data authResults:' + data.authResults);\\n}).catch((err: BusinessError) => {\\n  console.info('data:' + JSON.stringify(err));\\n});\\n\\n\`\`\`\\n\\n---\\n\\n*此图只做演示，不和上述代码具体效果一一对应*\\n\\n![image-20240608002954074](readme.assets/image-20240608002954074.png)\\n\\n### 4.访问接口-必须\\n\\n此时，就可以直接调用相关接口，实现业务功能\\n\\n### 5. 当用户拒绝时，二次申请权限\\n\\n针对以上弹窗，如果用户点击了**禁止**，我们可以再次弹窗询问用户，如 “不授予权则无法继续使用功能”，“禁止”，“允许”。\\n\\n此时，如果用户点击了允许\\n\\n1. 使用 [requestPermissionOnSetting](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/js-apis-abilityaccessctrl-V5#requestpermissiononsetting12)  在应用内直接弹窗 请求授权\\n\\n2. 使用 [startAbility](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/js-apis-inner-application-uiabilitycontext-V5#uiabilitycontextstartability)  跳转到系统权限设置页面，重新授权权限\`\\n\\n   \`\`\`typescript\\n   let want: Want = {\\n     bundleName: 'com.huawei.hmos.settings',\\n     abilityName: 'com.huawei.hmos.settings.MainAbility',\\n     uri: 'application_info_entry'\\n   };\\n   const ctx = getContext(this) as common.UIAbilityContext\\n   ctx.startAbility(want)\\n   \`\`\`\\n\\n   \\n\\n\\n\\n\\n\\n## 附上述流程思维导图\\n\\n![image-20240608010002233](readme.assets/image-20240608010002233.png)\\n\\n---\\n\\n![image-20240608010016337](readme.assets/image-20240608010016337.png)"}`),g={name:"鸿蒙开发技巧/鸿蒙应用开发权限一览/鸿蒙应用开发权限一览.md"};function d(b,s,y,u,A,C){return a(),e("div",null,[...s[0]||(s[0]=[l("",58)])])}const D=i(g,[["render",d]]);export{F as __pageData,D as default};
